import React, { useEffect, useRef, useState } from 'react';
import member from '../../../assets/member.png';
import President from '../../../assets/president.png';

const roles = [
  { title: 'President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
  { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
];

const members = Array(8).fill({
  title: 'Member',
  name: 'Mr. XYZabc Patel',
  img: member,
});

export default function CommitteeTreeDynamic() {
  const presidentRef = useRef(null);
  const rolesRefs = useRef([]);
  rolesRefs.current = [];
  
  const [lines, setLines] = useState([]);

  // Helper to add refs
  const addRoleRef = (el) => {
    if (el && !rolesRefs.current.includes(el)) {
      rolesRefs.current.push(el);
    }
  };

  useEffect(() => {
    function calculateLines() {
      if (!presidentRef.current || rolesRefs.current.length === 0) return;

      const presidentRect = presidentRef.current.getBoundingClientRect();

      const newLines = rolesRefs.current.map((roleEl) => {
        const roleRect = roleEl.getBoundingClientRect();

        // SVG coordinates relative to a container (we'll use window coords minus container top-left)
        // For simplicity, use window coords minus container top-left

        // Container top-left
        const container = document.getElementById('tree-container');
        const containerRect = container.getBoundingClientRect();

        // Start point: bottom center of president card relative to container
        const startX = presidentRect.left + presidentRect.width / 2 - containerRect.left;
        const startY = presidentRect.bottom - containerRect.top;

        // End point: top center of role card relative to container
        const endX = roleRect.left + roleRect.width / 2 - containerRect.left;
        const endY = roleRect.top - containerRect.top;

        // Control points for smooth curve:
        const controlPoint1 = { x: startX, y: (startY + endY) / 2 };
        const controlPoint2 = { x: endX, y: (startY + endY) / 2 };

        return { startX, startY, endX, endY, controlPoint1, controlPoint2 };
      });

      setLines(newLines);
    }

    calculateLines();
    window.addEventListener('resize', calculateLines);
    return () => window.removeEventListener('resize', calculateLines);
  }, []);

  return (
    <section
      id="tree-container"
      className="py-10 px-4 max-w-7xl mx-auto relative bg-white"
      style={{ minHeight: '600px' }}
    >
      <h2 className="text-2xl font-bold mb-12 text-center">Our Committee</h2>

      {/* President */}
      <div className="flex justify-center mb-16">
        <NodeCard ref={presidentRef} {...roles[0]} />
      </div>

      {/* Roles */}
      <div className="flex justify-center space-x-20 mb-14">
        {roles.slice(1).map((role, i) => (
          <NodeCard key={i} ref={addRoleRef} {...role} />
        ))}
      </div>

      {/* SVG for connectors */}
      <svg
        className="absolute top-0 left-0 w-full h-full pointer-events-none"
        style={{ zIndex: 0, overflow: 'visible' }}
      >
        {lines.map(({ startX, startY, endX, endY, controlPoint1, controlPoint2 }, i) => (
          <path
            key={i}
            d={`M${startX},${startY} C${controlPoint1.x},${controlPoint1.y} ${controlPoint2.x},${controlPoint2.y} ${endX},${endY}`}
            stroke="#F48F0F"
            strokeWidth="3"
            fill="none"
          />
        ))}
      </svg>

      {/* Members grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-12 max-w-5xl mx-auto mt-12">
        {members.map((member, i) => (
          <NodeCard key={i} {...member} />
        ))}
      </div>
    </section>
  );
}

// Forward ref to div inside NodeCard for measurement
const NodeCard = React.forwardRef(({ img, title, name }, ref) => (
  <div
    ref={ref}
    className="text-center p-4 border rounded shadow w-36 mx-auto bg-white"
    style={{ minWidth: '140px' }}
  >
    <img src={img} alt={title} className="w-20 h-20 mx-auto rounded-full mb-3 object-cover" />
    <div className="font-semibold text-md">{title}</div>
    <div className="text-xs text-gray-600">{name}</div>
  </div>
));
